    original: '龐蔥與太子質於邯鄲，謂魏王曰：『今一人言市有虎，王信之乎？』王曰：『否。』『二人言市有虎，王信之乎？』王曰：『寡人疑之矣。』『三人言市有虎，王信之乎？』王曰：『寡人信之矣。』龐蔥曰：『夫市之無虎明矣，然而三人言而成虎。今邯鄲去大梁也遠於市，而議臣者過於三人矣。願王察之矣。』',
