    original: '既罷歸國，以相如功大，拜爲上卿，位在廉頗之右。廉頗曰：『我爲趙將，有攻城野戰之大功，而藺相如徒以口舌爲勞，而位居我上……吾羞，不忍爲之下。』宣言曰：『我見相如，必辱之。』……已而相如出，望見廉頗，相如引車避匿。……相如曰：『……彊秦之所以不敢加兵於趙者，徒以吾兩人在也。今兩虎共鬥，其勢不倶生。吾所以爲此者，以先國家之急而後私讎也。』廉頗聞之，肉袒負荊，因賓客至藺相如門謝罪。',
