    situation: '小安誤會小芸偷拿文具，查清楚後當面道歉，也說明自己以後會先問清楚。',
    note: '「上卿」是最高的官位；「右」在這裡指地位較高；「肉袒」是脫下上衣露出肩背，「負荊」是背著荊條表示願意受罰。兩人後來成為刎頸之交。',
