    note: '「文首」是頭上有花紋，「喙」是鳥嘴，「其鳴自詨」是叫聲像在喊自己的名字「精衛」，「堙」是填塞；「溺而不返」是淹沒在海裡、再也沒有回來，「故為精衛」是女娃因此化成了精衛鳥。這是一則神話。',
