    original: '竹之始生，一寸之萌耳，而節葉具焉。……今畫者乃節節而為之，葉葉而累之，豈復有竹乎！故畫竹必先得成竹於胸中，執筆熟視，乃見其所欲畫者，急起從之，振筆直遂，以追其所見，如兔起鶻落，少縱則逝矣。與可之教予如此。',
