    original: '十年春，齊師伐我。公將戰，曹劌請見。……公與之乘。戰於長勺。公將鼓之。劌曰：『未可。』齊人三鼓，劌曰：『可矣。』齊師敗績。……既克，公問其故。對曰：『夫戰，勇氣也，一鼓作氣，再而衰，三而竭。彼竭我盈，故克之。……』',
