    note: '「齊師伐我」的「我」指魯國；曹劌是魯國平民，「乘」是一起坐戰車，「鼓」是擂鼓進攻，「敗績」是大敗，「竭」是用盡，「盈」是飽滿。這段就是國中課文〈曹劌論戰〉。',
