    original: '秦之圍邯鄲，趙使平原君求救，合從於楚，約與食客門下有勇力文武備具者二十人偕。……得十九人，餘無可取者，無以滿二十人。門下有毛遂者，前，自贊於平原君曰：『遂聞君將合從於楚，約與食客門下二十人偕，不外索。今少一人，願君即以遂備員而行矣。』平原君曰：『先生處勝之門下幾年於此矣？』毛遂曰：『三年於此矣。』平原君曰：『夫賢士之處世也，譬若錐之處囊中，其末立見。今先生處勝之門下三年於此矣，左右未有所稱誦，勝未有所聞，是先生無所有也。先生不能，先生留。』毛遂曰：『臣乃今日請處囊中耳。使遂蚤得處囊中，乃穎脫而出，非特其末見而已。』平原君竟與毛遂偕。……毛先生以三寸之舌，彊於百萬之師。',
    source: '《史記‧平原君虞卿列傳》(〈史記/卷076〉revid 7909284)',
