    note: '「合從」是聯合各國對抗秦國，「食客」是住在貴族家裡的人才，「自贊」是自我推薦，「錐」是錐子，「囊」是布袋，「穎脫而出」是整個錐子尖都露出來，成語「脫穎而出」由此來；「蚤」通「早」，「三寸之舌」指口才。毛遂後來靠口才說服楚王答應聯合救趙。',
