      '陳寔其實看見了，卻不聲張，只整理衣服並把子孫叫到客廳。',
      '他勸子孫要自我勉勵，說壞人不一定天生壞；大家抬頭看見樑上的小偷。',
      '小偷下來道歉，陳寔溫和扶他起來，送他兩匹絹布；小偷感動離開。',
