    original: '時歲荒民儉，有盜夜入其室，止於樑上。寔陰見，乃起自整拂，呼命子孫，正色訓之曰：『夫人不可不自勉。不善之人未必本惡，習以性成，遂至於此。樑上君子者是矣！』盜大驚，自投於地，稽顙歸罪。寔徐譬之曰：『視君狀貌，不似惡人，宜深克己反善。然此當由貧困。』令遺絹二匹。自是一縣無復盜竊。',
