    situation: '小翔一時衝動把同學的筆放進書包，老師了解原因後陪他歸還、道歉，並一起想下次怎麼做。',
    note: '「歲荒民儉」是那年收成不好、百姓窮困，「陰見」是暗中看見，「整拂」是整理衣服，「習以性成」是壞習慣久了就變成本性，「稽顙」是磕頭，「克己反善」是約束自己、回到善良，「遺」是送給。成語後來成為小偷的代稱，原典重點是陳寔體諒與勸人向善。',
