    meaning: '原指孔子反覆讀《易經》，把串竹簡的熟牛皮繩都弄斷多次；現在形容讀書非常勤奮、反覆鑽研。',
    example: '為了準備科展，小妍把資料讀了又讀、筆記改了又改，真有韋編三絕的精神。',
    situation: '小組研究一個難題時，大家把資料分段讀、彼此說明，直到真正弄懂為止。',
    note: '「韋」是熟牛皮，「編」是串竹簡的繩子，「三」表示多次，不是剛好三次；「晚」是晚年。「序彖、繫、象、說卦、文言」指替《易經》整理、寫解說，這些篇章合稱〈十翼〉，傳統說法認為是孔子所作，學者也有不同看法。',
