    original: '班超字仲升，扶風平陵人，徐令彪之少子也。爲人有大志，不修細節。……超與母隨至洛陽。家貧，常爲官傭書以供養。乆勞苦，甞輟業投筆歎曰：『大丈夫無它志略，猶當效傅介子、張騫立功異域，以取封侯，安能乆事筆研閒乎？』左右皆笑之。超曰：『小子安知壯士志哉！』',
