    original: '秋水時至，百川灌河，涇流之大，……不辯牛馬，於是焉，河伯欣然自喜，……順流而東行，至於北海，東面而視，不見水端，於是焉，河伯始旋其面目，望洋向若而歎，曰：『野語有之，曰「聞道百，以爲莫己若」者，我之謂也。……今我睹子之難窮也，吾非至於子之門，則殆矣！吾長見笑於大方之家！』',
