    original: '晉王羲之字逸少，曠子也。七歲善書。十二，見前代《筆說》於其父枕中，竊而讀之。……不盈期月，書便大進。衛夫人見，語太常王策曰：『此兒必見用筆訣，近見其書，便有老成之智。』……晉帝時，祭北郊文，更祝板，工人削之，筆入木三分。',
    source: '《太平廣記》卷二〇七〈王羲之〉引羊欣《筆陣圖》(〈太平廣記/卷第207〉revid 1762037)',
    meaning: '原指王羲之的墨跡深深滲進木板；現在比喻見解、分析或描寫非常深刻。',
    example: '她讀完小說後分析人物心情，說得入木三分，連同學原本沒注意的細節也找到了。',
    situation: '討論故事角色時，大家先引用情節和行動作證，再說自己的看法，避免只憑印象下結論。',
    note: '「善書」是字寫得好，「竊而讀之」是偷偷拿來讀，「不盈期月」是不到一個月，「大進」是大大進步。衛夫人是有名的女書法家；「祝板」是祭祀用來寫文字的木板，「削」是刨去表面。「入木三分」是誇張傳說，意思是筆力非常強；這段出自《太平廣記》卷二〇七所引羊欣《筆陣圖》，不是張懷瓘《書斷》。',
