    original: '漢元年十月，沛公兵遂先諸侯至霸上。……遂西入咸陽。欲止宮休舍，樊噲、張良諫，乃封秦重寶財物府庫，還軍霸上。召諸縣父老豪桀曰：『父老苦秦苛法久矣，誹謗者族，偶語者棄市。吾與諸侯約，先入關者王之，吾當王關中。與父老約，法三章耳：殺人者死，傷人及盜抵罪。餘悉除去秦法。……』……秦人大喜，爭持牛羊酒食獻饗軍士。沛公又讓不受，曰：『倉粟多，非乏，不欲費人。』人又益喜，唯恐沛公不為秦王。',
