    note: '「沛公」就是後來的漢高祖劉邦，「霸上」是地名，「休舍」是住下休息，「府庫」是收藏財物的倉庫，「豪桀」是地方上有聲望的人，「苛法」是嚴苛的法律，「誹謗者族」是批評朝廷的人要被滅族，「偶語者棄市」是兩個人私下談論就要在街市上處死，「王」(念ㄨㄤˋ)是稱王，「抵罪」是依所犯的罪受罰，「獻饗」是送食物慰勞，「讓」是推辭。在這之前秦王子嬰已經向沛公投降(漫畫不畫)。',
