    original: '大方無隅，大器晚成，大音希聲，大象無形，……琰從弟林，少無名望，雖姻族猶多輕之，而琰常曰：『此所謂大器晚成者也，終必遠至。』涿郡孫禮、盧毓始入軍府，琰又名之曰：『孫疏亮亢烈，剛簡能斷，盧清警明理，百鍊不消，皆公才也。』後林、禮、毓咸至鼎輔。',
    source: '《老子》第四十一章(〈道德經 (王弼本)〉revid 2354026);故事見《三國志‧魏書‧崔琰傳》(〈三國志/卷12〉revid 2085067)',
    meaning: '原指貴重的大器物要花很長的時間才能做成；比喻有大才能的人，往往比較晚才有成就。',
    example: '他小時候成績平平，後來努力不懈，成了知名的科學家，親友都說他大器晚成。',
    situation: '小芳學畫起步比同學晚，但她每天練習，到國三時作品入選了全市美展。',
    note: '老子原本用「大器晚成」來比喻「道」：最大的器物，最後才能完成；崔琰借這句話來形容人。「大方無隅」是最大的方形看不到邊角，「希聲」是聽不到聲音。「從弟」是堂弟，「名望」是名聲，「姻族」是親戚，「輕」是看不起，「遠至」是走得遠、有大成就，「名之」是評論他們，「公才」是能當三公(朝廷最高官位)的人才，「鼎輔」是輔佐君王的最高官位。「孫疏亮亢烈……盧清警明理……」是崔琰分別稱讚孫禮、盧毓的性情(漫畫只畫他稱讚)。',
