    original: '復拜東海相。之官，道經滎陽，令敦煌曹暠，咨之故孝廉也，迎路謁候，咨不為留。暠送至亭次，望塵不及，謂主簿曰：『趙君名重，今過界不見，必為天下笑！』即棄印綬，追至東海。謁咨畢，辭歸家。其為時人所貴若此。',
