    situation: '小捷跑步全班最快，大家都說望塵莫及，他卻主動教同學起跑的技巧。',
    note: '「拜」是任命官職，「東海相」是東海國的長官，「之官」是去上任，「令」是縣令，「孝廉」是漢代推薦人才做官的名目(趙咨當敦煌太守時推薦過曹暠)，「謁候」是迎接問候，「亭次」是路邊的驛亭，「主簿」是管文書的屬官，「過界」是經過自己的轄區，「印綬」是官印和繫印的帶子，「棄印綬」就是辭官。教育部《成語典》認為「望塵莫及」語本《莊子‧田子方》：顏淵對孔子說，老師快跑起來塵土都揚不起，我只能在後面瞪著眼看(原文「夫子奔逸絕塵而回瞠若乎後矣」)；《後漢書》這段則寫出了「望塵不及」四個字。',
