      '冉有問同樣的話，孔子說：「聽到了就去做。」',
      '公西華說：「同一個問題，老師的回答卻不一樣，我覺得疑惑，想請教老師。」',
      '孔子說：「冉求做事退縮，所以我推他向前；子路勇氣過人，所以我讓他退一步。」',
