    original: '子路問：『聞斯行諸？』子曰：『有父兄在，如之何其聞斯行之？』冉有問：『聞斯行諸？』子曰：『聞斯行之。』公西華曰：『由也問：「聞斯行諸？」子曰：「有父兄在。」求也問：「聞斯行諸？」子曰：「聞斯行之。」赤也惑，敢問。』子曰：『求也退，故進之；由也兼人，故退之。』',
    source: '《論語‧先進》(〈論語/先進第十一〉revid 11118105);成語四字語本程頤語(《二程遺書‧卷十九》,〈二程遺書/卷19〉revid 2000677)',
    meaning: '看每個人的個性和程度不同，用不同的方法來教導他。',
