    situation: '小雯當小老師教兩位同學，一位講一次就懂，一位要邊畫圖邊說明，她就用兩種方法分別教。',
    note: '「聞斯行諸」是聽到了就去做嗎，「如之何」是怎麼可以，「由」是子路(仲由)，「求」是冉有(冉求)，「赤」是公西華(公西赤)，「惑」是疑惑，「敢問」是冒昧請問，「退」是退縮，「進之」是讓他向前，「兼人」是一個人抵得上兩個人，形容勇氣過人。《論語》裡沒有「因材施教」四個字；宋代程頤說「孔子教人，各因其材」，後人才歸納成這句成語。',
