    note: '「骨肉」指親人，「讒賊」是說壞話挑撥的人，「間」(念ㄐㄧㄢˋ)是離間，「相危」是互相傷害，「所以養」是用來保養身體的東西，「害所養」是反而傷害了要保養的身體，「適」是配合，「履」是鞋子，「殺」是削減，「便冠」是讓帽子戴得上。原文是說：親人本來互相愛護，卻因為小人挑撥而互相傷害，就像削腳穿鞋、削頭戴帽一樣。原文沒有寫任何人物，漫畫照這個比喻畫，刀子沒有碰到腳。',
