    original: '其後，方平欲東之括蒼山，過吳，往胥門蔡經家。……其家假借盆甕作飲食數百斛，羅列覆置庭中，其日方平果來，……乘羽車，駕五龍，龍各異色，麾節幡旗，前後導從，威儀奕奕如大將軍也。……因遣人召麻姑相問，……麻姑至，蔡經亦舉家見之。是好女子，年十八九許，於頂中作髻，餘髮散垂至腰，其衣有文章而非錦綺，光彩耀日，不可名字，皆世所無有也。入拜方平，方平為之起立。坐定，召進行廚，皆金玉杯盤無限也，餚膳多是諸花果，而香氣達於內外，……麻姑自說：『接待以來，已見東海三為桑田，向到蓬萊，水又淺於往昔，會時略半也，豈將復還為陵陸乎。』方平笑曰：『聖人皆言，海中行復揚塵也。』',
