    note: '「方平」是神仙王方平(本篇題目作「王遠」)，「括蒼山」是山名，「吳」是吳地，「胥門」是吳城的城門，「盆甕」是盆子和甕，「斛」是容量單位，「羅列覆置」是排好、蓋起來放著，「羽車」是用羽毛裝飾的車，「麾節幡旗」是各種旗子，「導從」是在前面開路和在後面跟隨的人，「奕奕」是盛大的樣子，「好女子」是美麗的女子，「年十八九許」是大約十八九歲，「文章」是花紋，「錦綺」是錦緞，「不可名字」是說不出名稱，「行廚」是隨行帶來的酒菜，「餚膳」是菜餚，「接待以來」是自從上次見面以來，「桑田」是種桑樹的田，指陸地，「蓬萊」是傳說中的海上仙山，「陵陸」是陸地，「揚塵」是揚起塵土，意思是海水乾了又變成陸地。這是葛洪《神仙傳》裡的神仙故事。原文作「東海三為桑田」，沒有「滄海」二字。唐代類書《初學記》卷六也引了這段，字句略有不同。',
