    note: '「公」是魯哀公，「至自越」是從越國回來，「逆」是迎接，「五梧」是地名，舊注說在魯國南邊，「僕」是駕車的人，「二子」是季康子和孟武伯，「惡言」是難聽的話，「盡之」是問個清楚，「為祝」是起身敬酒祝壽，「惡郭重」的「惡」(念ㄨˋ)是討厭，「季孫」就是季康子，「飲彘」是罰孟武伯喝酒(「彘」是孟武伯的名字)，「密邇仇讎」是靠近敵國，「不獲從君」是沒能跟隨國君，「大行」是遠行，「食言」是說了話不算數，「始有惡」是開始有了嫌隙。孟武伯在宴會上拿郭重的外表開玩笑，反而被國君用「胖」字諷刺他說話不算話；拿別人的身材開玩笑，本來就不是好事。孟武伯就是《論語》裡向孔子問孝的那位。原文作「是食言多矣，能無肥乎」，成語說成「食言而肥」。頁面用「．」斷句，本表照錄。',
